+  border-radius:12px;
+  padding:12px 16px;
+  font-weight:700;
+  cursor:pointer;
+  display:inline-flex; align-items:center; justify-content:center;
+  gap:10px;
+  transition:transform .15s ease, filter .15s ease, background .15s ease;
