+  inset:-30%;
+  background:conic-gradient(from 210deg, rgba(229,9,20,.55), rgba(255,255,255,.14), rgba(0,0,0,0), rgba(229,9,20,.35));
+  transform:rotate(12deg);
+}
+.poster::after{
+  content:attr(data-title);
+  position:absolute;
+  inset:auto 12px 12px 12px;
+  font-weight:800;
+  letter-spacing:-.02em;
+  text-transform:uppercase;
+  font-size:11px;
+  color:rgba(255,255,255,.92);
+  text-shadow:0 10px 20px rgba(0,0,0,.8);
+}
+.hero-overlay{
+  position:absolute;
+  inset:0;
+  background:linear-gradient(180deg, rgba(0,0,0,.18), rgba(0,0,0,.9) 62%, rgba(0,0,0,.98));
+}
+
+.hero-inner{position:relative; padding:74px 0 50px}
+.hero-content{max-width:860px}
+.kicker{display:inline-flex; align-items:center; gap:10px; padding:8px 12px; border-radius:999px; border:1px solid rgba(255,255,255,.14); background:rgba(0,0,0,.35); color:var(--muted); font-weight:650}
+.kicker .dot{width:8px; height:8px; border-radius:999px; background:var(--accent); box-shadow:0 0 0 5px rgba(229,9,20,.18)}
+
+.h1{
+  margin:16px 0 10px;
+  font-size:clamp(36px, 4.2vw, 64px);
+  line-height:1.02;
+  letter-spacing:-.03em;
+}
