+  margin:0 0 16px;
+  font-size:clamp(18px, 1.6vw, 22px);
+  color:var(--muted);
+  font-weight:600;
+}
+.prompt{margin:0 0 18px; color:var(--muted); font-weight:550}
+
+.email-row{display:flex; gap:12px; align-items:stretch; max-width:720px}
+.input{
+  flex:1;
+  border-radius:14px;
+  border:1px solid rgba(255,255,255,.18);
+  background:rgba(0,0,0,.55);
+  padding:14px 14px;
+  outline:none;
+}
+.input:focus{border-color:rgba(229,9,20,.65); box-shadow:0 0 0 4px rgba(229,9,20,.16)}
+.btn-cta{
+  min-width:190px;
+  border-radius:14px;
+  font-size:16px;
+}
+.note{margin:12px 0 0; color:var(--muted2); font-size:14px}
+
+/* Sections */
+.section{padding:54px 0}
+.section-title{font-size:clamp(22px, 2.2vw, 34px); letter-spacing:-.02em; margin:0 0 18px}
+
+/* Trending carousel */
+.carousel-shell{
+  position:relative;
+  border-radius:var(--radius2);
+  background:linear-gradient(180deg, rgba(255,255,255,.06), rgba(255,255,255,.02));
+  border:1px solid rgba(255,255,255,.12);
+  box-shadow:var(--shadow2);
+  overflow:hidden;
+}
+.carousel-track{
+  display:flex;
+  gap:14px;
+  padding:20px;
+  overflow:auto;
+  scroll-snap-type:x mandatory;
+  scrollbar-width:thin;
+  scrollbar-color:rgba(255,255,255,.22) rgba(0,0,0,.12);
+}
+.carousel-track::-webkit-scrollbar{height:10px}
+.carousel-track::-webkit-scrollbar-thumb{background:rgba(255,255,255,.22); border-radius:999px}
+.carousel-track::-webkit-scrollbar-track{background:rgba(0,0,0,.12)}
+
+.title-card{
+  position:relative;
+  width:min(240px, 72vw);
+  flex:0 0 auto;
+  border-radius:22px;
+  overflow:hidden;
+  border:1px solid rgba(255,255,255,.10);
+  background:linear-gradient(135deg, rgba(255,255,255,.06), rgba(255,255,255,.015));
+  box-shadow:0 18px 46px rgba(0,0,0,.55);
+  scroll-snap-align:start;
+}
+.title-poster{aspect-ratio:2/3; display:block; width:100%; background:radial-gradient(200px 200px at 30% 30%, rgba(229,9,20,.45), rgba(229,9,20,0) 60%), linear-gradient(160deg, rgba(255,255,255,.10), rgba(0,0,0,.2));}
+.title-card:nth-child(3n+2) .title-poster{background:radial-gradient(200px 200px at 70% 35%, rgba(229,9,20,.4), rgba(229,9,20,0) 60%), linear-gradient(160deg, rgba(255,255,255,.10), rgba(0,0,0,.2));}
+.title-card:nth-child(3n) .title-poster{background:radial-gradient(200px 200px at 30% 70%, rgba(229,9,20,.38), rgba(229,9,20,0) 60%), linear-gradient(160deg, rgba(255,255,255,.10), rgba(0,0,0,.2));}
+
+.rank{
+  position:absolute;
+  left:14px;
+  bottom:18px;
+  font-size:92px;
+  font-weight:900;
+  letter-spacing:-.08em;
+  color:rgba(255,255,255,.14);
+  line-height:1;
+  text-shadow:0 18px 35px rgba(0,0,0,.65);
+}
+.title-name{
+  position:absolute;
+  inset:auto 14px 14px 14px;
+  padding-left:72px;
+  font-weight:800;
+  font-size:16px;
+  letter-spacing:-.02em;
+  text-shadow:0 12px 30px rgba(0,0,0,.85);
+}
+.title-tag{
+  position:absolute;
+  left:14px;
+  top:14px;
+  font-size:12px;
+  padding:7px 10px;
+  border-radius:999px;
+  background:rgba(0,0,0,.52);
+  border:1px solid rgba(255,255,255,.16);
+  color:rgba(255,255,255,.84);
+}
+
+.carousel-next{
+  position:absolute;
+  right:14px;
+  top:50%;
+  transform:translateY(-50%);
+  width:48px;
+  height:48px;
+  border-radius:999px;
+  background:rgba(0,0,0,.58);
+  border:1px solid rgba(255,255,255,.16);
+  box-shadow:0 14px 40px rgba(0,0,0,.6);
+}
+.carousel-next:hover{background:rgba(0,0,0,.72)}
