+.grid-4{display:grid; grid-template-columns:repeat(4, 1fr); gap:16px}
+.card{
+  border-radius:var(--radius);
+  background:linear-gradient(180deg, rgba(255,255,255,.08), rgba(255,255,255,.02));
+  border:1px solid rgba(255,255,255,.12);
+  padding:18px;
+  min-height:170px;
+  position:relative;
+  box-shadow:var(--shadow2);
+}
+.card h3{margin:0 0 8px; letter-spacing:-.02em}
+.card p{margin:0; color:var(--muted)}
+.icon-badge{
+  position:absolute;
+  right:14px;
+  bottom:14px;
+  width:42px;
+  height:42px;
+  border-radius:14px;
+  background:rgba(229,9,20,.16);
+  border:1px solid rgba(229,9,20,.32);
+  display:grid; place-items:center;
+}
+.icon-badge svg{width:22px; height:22px; fill:rgba(255,255,255,.92)}
+
+/* FAQ */
+.faq{
+  border-radius:var(--radius2);
+  background:linear-gradient(180deg, rgba(255,255,255,.06), rgba(255,255,255,.02));
+  border:1px solid rgba(255,255,255,.12);
+  overflow:hidden;
+  box-shadow:var(--shadow2);
+}
+.faq-item{border-top:1px solid rgba(255,255,255,.10)}
+.faq-item:first-child{border-top:0}
+.faq-q{
+  width:100%;
+  text-align:left;
+  background:transparent;
+  border:0;
+  padding:18px 18px;
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:16px;
+  cursor:pointer;
+}
+.faq-q span{font-weight:800; letter-spacing:-.01em; font-size:18px}
+.chev{
+  width:22px; height:22px;
+  border-radius:999px;
+  border:1px solid rgba(255,255,255,.16);
+  display:grid; place-items:center;
+  background:rgba(0,0,0,.35);
+  flex:0 0 auto;
+  transition:transform .2s ease;
+}
+.faq-a{
+  display:grid;
+  grid-template-rows:0fr;
+  transition:grid-template-rows .24s ease;
+}
+.faq-a > div{overflow:hidden; padding:0 18px; color:var(--muted)}
+.faq-a p{margin:0; padding:0 0 18px}
+.faq-item[data-open="true"] .faq-a{grid-template-rows:1fr}
+.faq-item[data-open="true"] .chev{transform:rotate(45deg)}
+
+/* CTA */
+.cta{
+  border-radius:var(--radius2);
+  background:
+    radial-gradient(900px 380px at 20% 30%, rgba(229,9,20,.35), rgba(229,9,20,0) 60%),
+    linear-gradient(180deg, rgba(255,255,255,.08), rgba(255,255,255,.02));
+  border:1px solid rgba(255,255,255,.12);
+  padding:26px;
+  box-shadow:var(--shadow);
+}
+
+/* Footer */
+.footer{padding:44px 0 60px; color:rgba(255,255,255,.7)}
+.footer-top{margin:0 0 18px}
+.footer-grid{display:grid; grid-template-columns:repeat(4, 1fr); gap:14px}
+.footer a{color:rgba(255,255,255,.7); text-decoration:underline; text-decoration-color:rgba(255,255,255,.25); text-underline-offset:3px}
+.footer a:hover{color:#fff}
+.fine{margin-top:18px; color:rgba(255,255,255,.55); font-size:13px}
+
+/* Login */
+.login-wrap{min-height:calc(100vh - 78px); display:grid; place-items:center; padding:44px 0}
+.panel{
+  width:min(460px, 100%);
+  border-radius:24px;
+  background:rgba(20,20,20,.86);
+  border:1px solid rgba(255,255,255,.12);
+  box-shadow:var(--shadow);
+  padding:22px;
+}
+.panel h1{margin:0 0 6px; letter-spacing:-.02em; font-size:28px}
+.panel p{margin:0 0 16px; color:var(--muted)}
+.field{display:grid; gap:8px; margin-bottom:12px}
+.label{color:rgba(255,255,255,.72); font-size:13px; font-weight:650}
+.help{
+  margin-top:14px;
+  border-top:1px solid rgba(255,255,255,.12);
+  padding-top:14px;
+}
+.help-toggle{
+  background:transparent;
+  border:0;
+  padding:0;
+  cursor:pointer;
+  color:rgba(255,255,255,.82);
+  text-decoration:underline;
